t.script:
async function ddLoadUsers() {
    const response = await fetch('/server_monitor/users/data', {
        method: 'POST', headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {}, id: Date.now()})
    });
    const payload = await response.json(); const data = payload.result || {};
    document.getElementById('dd-users').textContent = data.active_users || 0;
    document.getElementById('dd-tabs').textContent = data.active_tabs || 0;
    document.getElementById('dd-consumption').textContent = (data.total_heartbeats || 0).toLocaleString();
    document.getElementById('dd-traffic').textContent = (data.total_navigations || 0).toLocaleString();
    const users = data.users || [];
    const maximum = Math.max(1, ...users.map(u => u.heartbeats + u.navigations));
    document.getElementById('dd-user-chart').innerHTML = users.map(u => {
        const total = u.heartbeats + u.navigations;
        const width = Math.max(2, Math.round(total * 100 / maximum));
        return `<div class="dd-user-bar" title="${u.heartbeats} latidos · ${u.navigations} navegaciones"><div class="dd-user-name">${u.name}</div><div class="dd-bar-track"><div class="dd-bar-fill" style="width:${width}%"></div></div><div class="dd-bar-value">${total}</div></div>`;
    }).join('') || '<div class="text-muted">No hay tráfico activo.</div>';
    const devices = data.devices || [];
    const maxDevice = Math.max(1, ...devices.map(d => d.value));
    document.getElementById('dd-device-chart').innerHTML = devices.map(d => `<div class="dd-device-row"><strong>${d.name}</strong><div class="dd-device-track"><div class="dd-device-fill" style="width:${Math.round(d.value * 100 / maxDevice)}%"></div></div><strong>${d.value}</strong></div>`).join('') || '<div class="text-muted">No hay dispositivos activos.</div>';
    const rows = users.map(u => `<tr><td><strong>${u.name}</strong></td><td>${u.devices.join(', ')}</td><td>${u.tabs}</td><td>${u.paths.join('<br/>')}</td><td>${u.navigations}</td><td>${u.heartbeats}</td><td>${u.last_seen}</td></tr>`).join('');
    document.getElementById('dd-user-rows').innerHTML = rows || '<tr><td colspan="7">No hay usuarios activos.</td></tr>';
}
ddLoadUsers(); setInterval(ddLoadUsers, 15000);
